{
  "name": "@endlex/omo-preset-switch",
  "version": "1.0.2",
  "description": "Process-scoped oh-my-opencode-slim preset switcher for OpenCode: TUI picker (/omopreset) + server-side model rewrite, zero LLM turns.",
  "type": "module",
  "license": "MIT",
  "author": "endlex",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "oh-my-opencode-slim",
    "preset",
    "tui"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/endlex/omo-preset-switch.git"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    }
  },
  "scripts": {
    "clean": "rm -rf dist",
    "build": "bun run clean && bun build src/index.ts src/tui.ts --outdir dist --target node --format esm --external @opencode-ai/plugin --external @opencode-ai/plugin/* --external @opencode-ai/sdk --external @opencode-ai/sdk/* --external @opentui/core --external @opentui/solid && bun run build:types",
    "build:types": "tsc --emitDeclarationOnly --declaration --declarationMap false --outDir dist --rootDir src --module esnext --moduleResolution bundler --target esnext --skipLibCheck --types node src/index.ts src/tui.ts",
    "prepublishOnly": "bun run build",
    "typecheck": "tsc --noEmit --skipLibCheck --moduleResolution bundler --module esnext --target esnext --types node src/index.ts src/tui.ts"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.3.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.3.6",
    "@types/node": "^22.0.0",
    "typescript": "^5.8.0"
  },
  "engines": {
    "node": ">=18"
  }
}
